use std::thread;

fn main() {
    let name = String::from("rust");
    let h = thread::spawn(|| {
        println!("{name}");
    });
    h.join().unwrap();
}

use std::thread;

fn main() {
    let hs: Vec<_> = (1..=3)
        .map(|i| thread::spawn(move || i * 2))
        .collect();
    let r: Vec<i32> = hs.into_iter().map(|h| h.join().unwrap()).collect();
    println!("{r:?}");
}

use std::thread;

fn main() {
    let mut total: i32 = 0;
    let data = [1, 2, 3];
    thread::scope(|s| {
        s.spawn(|| {
            total = data.iter().sum();
        });
    });
    println!("{total}");
}

use std::thread;

fn main() {
    let h = thread::spawn(|| {
        if true {
            panic!("boom");
        }
        5
    });
    let r = h.join();
    println!("{}", r.is_err());
}
